package app.dayflow;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import org.json.*;

/** One canvas for 365 dates avoids hundreds of native child views in a year overview. */
public final class YearOverview extends View {
    private final MainActivity a;private final int year;private final LinearLayout preview;private LocalDate selected;private long lastTap;private LocalDate lastDay;private final Paint paint=new Paint(3);
    private YearOverview(MainActivity a,int year,LocalDate selected,LinearLayout preview){super(a);this.a=a;this.year=year;this.selected=selected;this.preview=preview;setContentDescription(year+"年日期概览，单击预览，双击打开周视图");}
    public static void add(MainActivity a,LinearLayout page,LocalDate initial){LinearLayout preview=Ui.column(a);YearOverview view=new YearOverview(a,initial.getYear(),initial,preview);page.addView(preview);page.addView(view,new LinearLayout.LayoutParams(-1,Ui.dp(a,1200)));view.preview();}
    private float monthHeight(){return Ui.dp(a,200);}
    protected void onDraw(Canvas c){super.onDraw(c);float half=getWidth()/2f,h=monthHeight(),top=Ui.dp(a,32),cell=(half-Ui.dp(a,12))/7f,line=Ui.dp(a,24);for(int month=1;month<=12;month++){float left=((month-1)%2)*half,y=((month-1)/2)*h;paint.setTextAlign(Paint.Align.LEFT);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextSize(Ui.dp(a,16));paint.setColor(Ui.ink(a));c.drawText(month+"月",left+Ui.dp(a,6),y+Ui.dp(a,22),paint);paint.setTypeface(Typeface.DEFAULT);paint.setTextSize(Ui.dp(a,12));paint.setTextAlign(Paint.Align.CENTER);String[] days={"一","二","三","四","五","六","日"};for(int col=0;col<7;col++){paint.setColor(Ui.muted(a));c.drawText(days[col],left+(col+.5f)*cell,y+top+Ui.dp(a,12),paint);}LocalDate first=LocalDate.of(year,month,1);int offset=first.getDayOfWeek().getValue()-1;for(int day=1;day<=first.lengthOfMonth();day++){LocalDate date=first.withDayOfMonth(day);int index=offset+day-1;float x=left+(index%7+.5f)*cell,baseline=y+top+(index/7+1)*line+Ui.dp(a,12);boolean chosen=date.equals(selected);if(chosen){paint.setColor(Ui.primary(a));c.drawCircle(x,baseline-Ui.dp(a,4),Ui.dp(a,10),paint);}paint.setColor(chosen?Ui.color(a,com.google.android.material.R.attr.colorOnPrimary):date.equals(LocalDate.now())?Ui.primary(a):Ui.ink(a));c.drawText(Integer.toString(day),x,baseline,paint);}}}
    public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float half=getWidth()/2f,cell=(half-Ui.dp(a,12))/7f;int colMonth=e.getX()<half?0:1,rowMonth=(int)(e.getY()/monthHeight()),month=rowMonth*2+colMonth+1;if(month<1||month>12)return true;float x=e.getX()-colMonth*half,y=e.getY()-rowMonth*monthHeight()-Ui.dp(a,32);int col=(int)(x/cell),row=(int)(y/Ui.dp(a,24))-1;if(col<0||col>6||row<0||row>5)return true;LocalDate first=LocalDate.of(year,month,1);int day=row*7+col-(first.getDayOfWeek().getValue()-1)+1;if(day<1||day>first.lengthOfMonth())return true;LocalDate chosen=first.withDayOfMonth(day);long now=android.os.SystemClock.uptimeMillis();if(chosen.equals(lastDay)&&now-lastTap<500){PlanHub.calendar(a,chosen,"week");return true;}lastDay=chosen;lastTap=now;selected=chosen;performClick();invalidate();preview();a.message(chosen+" · "+ChineseDates.label(chosen)+"，再次点击打开本周");return true;}
    public boolean performClick(){super.performClick();return true;}
    private void preview(){preview.removeAllViews();preview.addView(Ui.text(a,selected+" · "+ChineseDates.label(selected),20,true));preview.addView(Ui.button(a,"打开所选日期的一周",true,()->PlanHub.calendar(a,selected,"week")));try{JSONArray rows=Data.get(a).dayTasks(selected);for(int i=0;i<Math.min(30,rows.length());i++){JSONObject r=rows.getJSONObject(i);preview.addView(Ui.button(a,r.optString("title")+" · "+PlanTime.label(r),false,()->a.detail(r)));}if(rows.length()==0)preview.addView(Ui.help(a,"当天没有安排"));}catch(Exception e){a.message(e.getMessage());}setContentDescription(year+"年日期概览，已选择"+selected);}
}
